namespace DockForge;
public sealed class SetupWizard : Window {
 readonly Bar bar=new(){Name="My workspace",Mode=BarMode.Launcher};readonly ContentControl body=new();readonly Button next;readonly Button back;int step;
 public SetupWizard(){Title="Welcome to DockForge";Width=650;Height=600;MinWidth=520;MinHeight=480;WindowStartupLocation=WindowStartupLocation.CenterScreen;bar.Monitors=[Monitor.All().FirstOrDefault(m=>m.Primary)?.Id??Monitor.All()[0].Id];var root=new DockPanel{Margin=new Thickness(30)};var heading=new StackPanel();heading.Children.Add(Ui.Text("Welcome to DockForge",30,true));heading.Children.Add(Ui.Text("A workspace that fits the way you work.",15));DockPanel.SetDock(heading,Dock.Top);root.Children.Add(heading);var footer=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,18,0,0)};back=Ui.Action("Back",()=>{step--;Render();});next=Ui.Action("Next",()=>{if(step<2){step++;Render();return;}try{App.Host.Config.Bars.Add(bar);App.Host.Config.SetupComplete=true;App.Host.Commit();Close();}catch(Exception e){App.Host.Config.Bars.Remove(bar);App.Host.Config.SetupComplete=false;MessageBox.Show(e.Message,"Could not create bar");}});footer.Children.Add(Ui.Action("Set up later",()=>Close()));footer.Children.Add(back);footer.Children.Add(next);DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);root.Children.Add(body);Content=root;Render();}
 void Render(){back.IsEnabled=step>0;next.Content=step==2?"Create my bar":"Next";var p=new StackPanel();p.Children.Add(Ui.Text($"Step {step+1} of 3",12));if(step==0){p.Children.Add(Ui.Text("Choose a display and position",23,true));Ui.Input(p,"Bar name",bar.Name,v=>bar.Name=v);Ui.Label(p,"Display");var displays=Monitor.All();var choice=new ComboBox{ItemsSource=displays,SelectedItem=displays.Find(m=>bar.Monitors.Contains(m.Id))};choice.SelectionChanged+=(_,_)=>{if(choice.SelectedItem is Monitor m)bar.Monitors=[m.Id];};p.Children.Add(choice);Ui.Choice(p,"Position",bar.Edge,v=>bar.Edge=v);}
  else if(step==1){p.Children.Add(Ui.Text("What should your bar show?",23,true));Ui.Choice(p,"Bar mode",bar.Mode,v=>bar.Mode=v);p.Children.Add(Ui.Text("Launcher holds your shortcuts and groups. Running apps shows open windows. Combined brings both together."));Ui.Choice(p,"Visibility",bar.Visibility,v=>bar.Visibility=v);Ui.Check(p,"Start DockForge when I sign in",App.Host.Config.StartAtSignIn,v=>App.Host.Config.StartAtSignIn=v);}
  else{p.Children.Add(Ui.Text("Start empty or choose your apps",23,true));var count=Ui.Text(bar.Items.Count==0?"Your bar is empty. You can add items at any time.":$"{bar.Items.Count} apps selected.");p.Children.Add(count);p.Children.Add(Ui.Action("Choose installed apps",()=>{var picker=new AppPicker{Owner=this};if(picker.ShowDialog()==true){bar.Items.AddRange(picker.Selected);count.Text=$"{bar.Items.Count} apps selected.";}}));p.Children.Add(Ui.Text("Right-click your bar to add items, create groups, or open Settings. Drag its handle to move it.\n\nYour Windows taskbar stays visible unless you choose to hide it in Settings."));}
  body.Content=new ScrollViewer{Content=p,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};
 }
}
